for slug, add in EXTRA.items():
    p = OUT / f"{slug}.yaml"
    d = yaml.safe_load(p.read_text(encoding="utf-8"))
    if add not in d["summary"]:
        d["summary"] = d["summary"].rstrip("\n") + "\n" + add
    p.write_text(yaml.safe_dump(d, allow_unicode=True, sort_keys=False, width=100000, default_flow_style=False), encoding="utf-8")
    print(slug, len(d["summary"]))
